import { useEffect, useMemo, useRef, useState } from 'react'
import {
  ArrowLeft,
  ArrowUpRight,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Filter,
  Play,
  Plus,
  Reload,
  X,
} from '@openai/apps-sdk-ui/components/Icon'
import {
  BoundedCache,
  DEFAULT_STATE,
  decodeJsonString,
  findBlockedKeyword,
  normalizeStoredState,
  normalizeText,
} from './klix-core.js'

const BACKFILL_URLS = [
  'https://www.klix.ba/',
  'https://www.klix.ba/vijesti',
  'https://www.klix.ba/biznis',
  'https://www.klix.ba/sport',
  'https://www.klix.ba/magazin',
  'https://www.klix.ba/lifestyle',
  'https://www.klix.ba/scitech',
  'https://www.klix.ba/auto',
]

const SOURCES = [
  { key: 'popular', label: 'Najčitanije', urls: ['https://www.klix.ba/najcitanije', ...BACKFILL_URLS] },
  { key: 'latest', label: 'Najnovije', urls: ['https://www.klix.ba/najnovije', ...BACKFILL_URLS] },
]

const CATEGORY_LABELS = {
  vijesti: 'Vijesti',
  sport: 'Sport',
  biznis: 'Biznis',
  magazin: 'Magazin',
  lifestyle: 'Lifestyle',
  scitech: 'SciTech',
  auto: 'Auto',
}

// The image proxy is only needed for hosts that reject a direct <img> request.
// Keep successful data URLs for this app session so returning from the reader
// does not turn the feed back into a row of fresh image downloads.
const proxiedImageCache = new BoundedCache(48)
const imageWarmCache = new BoundedCache(120)
const instagramPostCache = new BoundedCache(24)
const LOGO_DATA = 'data:image/png;base64,'

async function loadState() {
  const data = await window.mobius.storage.get('settings.json')
  return normalizeStoredState(data === null ? DEFAULT_STATE : data)
}

async function saveState(data) {
  await window.mobius.storage.set('settings.json', data)
}

function absoluteUrl(href) {
  try {
    return new URL(href, 'https://www.klix.ba').href
  } catch {
    return href
  }
}

function categoryFromUrl(url) {
  try {
    const parts = new URL(url).pathname.split('/').filter(Boolean)
    return CATEGORY_LABELS[parts[0]] || (parts[0] ? parts[0][0].toUpperCase() + parts[0].slice(1) : 'Klix')
  } catch {
    return 'Klix'
  }
}

function cleanText(text) {
  return (text || '').replace(/\s+/g, ' ').trim()
}

function extractImage(anchor) {
  const img = anchor.querySelector('img')
  const source = anchor.querySelector('picture source')
  if (!img && !source) return ''
  const candidates = [
    img?.getAttribute('data-src'),
    img?.getAttribute('data-srcset'),
    img?.getAttribute('data-original'),
    source?.getAttribute('data-srcset'),
    source?.getAttribute('srcset'),
    img?.getAttribute('srcset'),
    img?.getAttribute('src'),
  ].filter(Boolean)
  for (const candidate of candidates) {
    const first = candidate.split(',')[0].trim().split(/\s+/)[0]
    if (!first || first.startsWith('data:')) continue
    return absoluteUrl(first)
  }
  return ''
}

function metaContent(doc, selector) {
  return doc.querySelector(selector)?.getAttribute('content') || ''
}

function parseJsonLd(doc) {
  for (const script of doc.querySelectorAll('script[type="application/ld+json"]')) {
    try {
      const data = JSON.parse(script.textContent || '{}')
      const items = Array.isArray(data) ? data : [data]
      const article = items.find((item) => item && (item['@type'] === 'NewsArticle' || item.headline))
      if (article) return article
    } catch {}
  }
  return {}
}

function extractGalleryImages(doc, seenImg) {
  const images = []
  const seenGalleryKeys = new Set()
  function galleryKey(src) {
    return src.replace(/_(?:th|xl|xxl)(?=\.jpg)/, '').replace(/([?&]v=)\d+/, '$1')
  }
  function addGalleryImage(srcValue, captionValue = '') {
    const src = absoluteUrl(decodeJsonString(srcValue))
    const key = galleryKey(src)
    if (!src || seenImg.has(src) || seenGalleryKeys.has(key)) return
    seenImg.add(src)
    seenGalleryKeys.add(key)
    images.push({ src, caption: cleanText(decodeJsonString(captionValue || '')) })
  }
  for (const script of doc.querySelectorAll('script[type="application/ld+json"], script')) {
    const text = script.textContent || ''
    if (!/ImageGallery|contentUrl|openPhotoSwipe/.test(text)) continue
    const galleryRe = /"contentUrl"\s*:\s*"([^"]+)"[\s\S]*?"caption"\s*:\s*"([^"]*)"/g
    let match
    while ((match = galleryRe.exec(text))) addGalleryImage(match[1], match[2])
    const photoswipeRe = /src\s*:\s*"([^"]*(?:_xl|_xxl)\.jpg[^"]*)"/g
    while ((match = photoswipeRe.exec(text))) addGalleryImage(match[1])
  }
  // Newer Klix galleries are rendered as clickable photo items rather than a
  // JSON payload. Their data attributes contain the full-resolution image.
  doc.querySelectorAll('[data-pswp-src], [data-fancybox], [data-gallery]').forEach((node) => {
    const src = node.getAttribute('data-pswp-src')
      || node.getAttribute('data-src')
      || node.getAttribute('href')
      || node.querySelector('img')?.getAttribute('data-src')
      || node.querySelector('img')?.getAttribute('src')
      || ''
    const caption = node.getAttribute('data-caption')
      || node.querySelector('img')?.getAttribute('alt')
      || ''
    addGalleryImage(src, caption)
  })
  return images
}


function youtubeIdFromUrl(src) {
  try {
    const url = new URL(src, 'https://www.klix.ba')
    if (/youtu\.be$/.test(url.hostname)) return url.pathname.split('/').filter(Boolean)[0] || ''
    if (/youtube(?:-nocookie)?\.com$/.test(url.hostname)) {
      if (url.pathname.startsWith('/embed/')) return url.pathname.split('/').filter(Boolean)[1] || ''
      return url.searchParams.get('v') || ''
    }
    if (/klix\.ba$/.test(url.hostname) && url.pathname === '/xplayer') return url.searchParams.get('v') || ''
  } catch {}
  return ''
}

function normalizeEmbedSrc(src, articleId = '') {
  if (!src) return ''
  const absolute = absoluteUrl(src)
  const youtubeId = youtubeIdFromUrl(absolute)
  if (youtubeId) return `https://www.klix.ba/xplayer?v=${encodeURIComponent(youtubeId)}${articleId ? `&sifra=${encodeURIComponent(articleId)}` : ''}`
  return absolute
}

function embedKey(src) {
  const youtubeId = youtubeIdFromUrl(src)
  return youtubeId ? `youtube:${youtubeId}` : src
}

function isSupportedVideoEmbed(src) {
  return /klix\.ba\/video\//.test(src)
    || /klix\.ba\/xplayer\?/.test(src)
    || /youtube(?:-nocookie)?\.com|youtu\.be|vimeo\.com/.test(src)
}

function extractVideoObjectEmbeds(doc) {
  const embeds = []
  for (const script of doc.querySelectorAll('script[type="application/ld+json"], script')) {
    const text = script.textContent || ''
    if (!/VideoObject|embedUrl/.test(text)) continue
    const re = /"embedUrl"\s*:\s*"([^"]+)"/g
    let match
    while ((match = re.exec(text))) embeds.push(decodeJsonString(match[1]))
  }
  return embeds
}

function parseArticleDetail(html, fallback = {}) {
  const doc = new DOMParser().parseFromString(html, 'text/html')
  const json = parseJsonLd(doc)
  const title = cleanText(doc.querySelector('h1')?.textContent) || json.headline || fallback.title || ''
  const articleId = (fallback.url || '').match(/\/(\d{9})(?:[/?#]|$)/)?.[1] || ''
  const lead = cleanText(doc.querySelector('.lead')?.textContent)
  const textRoot = doc.querySelector('#text') || doc.querySelector('article.content') || doc
  const imageFromJson = Array.isArray(json.image) ? json.image[0] : json.image
  const heroImage = absoluteUrl(
    doc.querySelector('.article_photo')?.getAttribute('src') ||
    metaContent(doc, 'meta[property="og:image"]') ||
    imageFromJson ||
    fallback.image ||
    ''
  )
  const blocks = []
  const paragraphs = []
  const seenImg = new Set(heroImage ? [heroImage] : [])
  const seenEmbeds = new Set()
  const parserIssues = []
  function addVideoEmbed(rawSrc) {
    const src = normalizeEmbedSrc(rawSrc, articleId)
    const key = embedKey(src)
    if (!src || !isSupportedVideoEmbed(src) || seenEmbeds.has(key)) return false
    seenEmbeds.add(key)
    blocks.push({ type: 'video', src })
    return true
  }
  const SKIP_CLASSES = ['article_tags', 'related', 'article_share', 'comments', 'tags-list']
  function walk(node) {
    if (!node || node.nodeType !== 1) return
    const tag = node.tagName.toLowerCase()
    const cls = node.getAttribute && (node.getAttribute('class') || '')
    if (cls && SKIP_CLASSES.some((k) => cls.includes(k))) return
    if (tag === 'script' || tag === 'style' || tag === 'noscript') return
    if (cls && /youtube/.test(cls)) {
      const id = node.getAttribute('data-id') || node.querySelector?.('[data-id]')?.getAttribute('data-id') || ''
      if (id) addVideoEmbed(`https://www.youtube-nocookie.com/embed/${id}?rel=0&playsinline=1`)
    }
    // Instagram posts/reels embed as <blockquote class="instagram-media"
    // data-instgrm-permalink="..."> (wrapped in .igembed). Klix relies on
    // Instagram's embed.js to hydrate it, which never runs in our reader — so
    // turn the permalink into Instagram's own /embed iframe and show it inline.
    if (cls && /instagram-media|igembed/.test(cls)) {
      const link = node.getAttribute('data-instgrm-permalink')
        || node.querySelector?.('[data-instgrm-permalink]')?.getAttribute('data-instgrm-permalink')
        || node.querySelector?.('a[href*="instagram.com"]')?.getAttribute('href')
        || ''
      const m = link.match(/instagram\.com\/(p|reel|tv)\/([A-Za-z0-9_-]+)/)
      if (m) blocks.push({ type: 'embed', provider: 'instagram', src: `https://www.instagram.com/${m[1]}/${m[2]}/` })
      return
    }
    if (tag === 'p') {
      // Klix sometimes nests <style>.related{...}</style> inside a <p> (the
      // related-articles widget). node.textContent would slurp that CSS into
      // the paragraph, dumping raw stylesheet rules into the reader — strip
      // style/script/noscript before reading the text.
      let textSource = node
      if (node.querySelector && node.querySelector('style, script, noscript')) {
        textSource = node.cloneNode(true)
        textSource.querySelectorAll('style, script, noscript').forEach((n) => n.remove())
      }
      const text = cleanText(textSource.textContent)
      if (text.length > 35) {
        blocks.push({ type: 'p', text })
        paragraphs.push(text)
      } else if (text.length > 0 && /^[A-ZČĆŠĐŽ]/.test(text) && text.length < 80 && node.querySelector('b, strong')) {
        blocks.push({ type: 'h', text })
      }
      // Also scan p for inline media inside it (Klix wraps videos in <p><center>...)
      const innerMedia = node.querySelectorAll('iframe, video, img')
      innerMedia.forEach((m) => walk(m))
      return
    }
    if (tag === 'img') {
      const isEditorial = /(?:^|\s)(?:my-0|max-h-300|mx-auto)(?:\s|$)/.test(cls || '')
      const alt = cleanText(node.getAttribute('alt') || '')
      if (!isEditorial || !alt) return
      let src = node.getAttribute('data-src') || node.getAttribute('data-srcset') || node.getAttribute('src') || ''
      src = src.split(/\s+/)[0]
      if (!src || /1x1\.png|placeholder/i.test(src)) return
      const absSrc = absoluteUrl(src)
      if (seenImg.has(absSrc)) return
      seenImg.add(absSrc)
      blocks.push({ type: 'img', src: absSrc, caption: alt })
      return
    }
    if (tag === 'iframe') {
      const raw = node.getAttribute('data-src') || node.getAttribute('src') || ''
      const src = normalizeEmbedSrc(raw, articleId)
      const supported = isSupportedVideoEmbed(src)
      const added = addVideoEmbed(src)
      if (!added && !supported && src && !/doubleclick|googlesyndication|adservice|facebook\.com\/plugins|twitter\.com\/widgets/i.test(src)) {
        parserIssues.push({ kind: 'unsupported-iframe', src })
      }
      return
    }
    if (tag === 'video') {
      const srcAttr = node.getAttribute('src') || node.querySelector('source')?.getAttribute('src') || ''
      const src = absoluteUrl(srcAttr)
      if (src && !/1x1\.png/i.test(src)) blocks.push({ type: 'nativeVideo', src, poster: absoluteUrl(node.getAttribute('poster') || '') })
      return
    }
    for (const child of node.children) walk(child)
  }
  // Klix places some lead media, especially its own video iframe, above the
  // text container. Scan the full page for supported media before walking text.
  extractVideoObjectEmbeds(doc).forEach((src) => addVideoEmbed(src))
  doc.querySelectorAll('iframe, .youtube[data-id], .youtube [data-id]').forEach((node) => walk(node))
  const galleryImages = extractGalleryImages(doc, seenImg)
  if (galleryImages.length > 1) blocks.push({ type: 'gallery', images: galleryImages })
  walk(textRoot)
  const cappedBlocks = blocks.slice(0, 60)
  const caption = cleanText(doc.querySelector('.article_photo')?.getAttribute('alt') || doc.querySelector('figcaption')?.textContent || '')
  const author = cleanText(json.author?.name || '')
  const published = json.datePublished || metaContent(doc, 'meta[property="article:published_time"]') || ''
  const cappedParagraphs = paragraphs.slice(0, 24)
  const bodyText = [lead, ...cappedParagraphs].join(' ')
  return { title, lead, paragraphs: cappedParagraphs, blocks: cappedBlocks, image: heroImage, caption, author, published, bodyText, fetched: true, parserIssues }
}

function parseArticles(html, sourceKey) {
  const doc = new DOMParser().parseFromString(html, 'text/html')
  const byUrl = new Map()
  const order = []

  doc.querySelectorAll('a[href]').forEach((anchor) => {
    const href = anchor.getAttribute('href') || ''
    if (!/\/\d{9}(?:[/?#]|$)/.test(href)) return
    const url = absoluteUrl(href)
    const text = cleanText(anchor.textContent)
    if (/komentari|podijeli|facebook|twitter/i.test(text)) return

    let entry = byUrl.get(url)
    if (!entry) {
      entry = { url, title: '', image: '', category: categoryFromUrl(url) }
      byUrl.set(url, entry)
      order.push(url)
    }
    if (!entry.title && text.length >= 34) entry.title = text
    if (!entry.title) {
      const alt = anchor.querySelector('img')?.getAttribute('alt') || ''
      const cleanAlt = cleanText(alt)
      if (cleanAlt.length >= 34) entry.title = cleanAlt
    }
    if (!entry.image) {
      const img = extractImage(anchor)
      if (img) entry.image = img
    }
  })

  const articles = []
  for (const url of order) {
    const entry = byUrl.get(url)
    if (!entry.title) continue
    articles.push({
      id: `${sourceKey}-${articles.length + 1}`,
      source: sourceKey,
      rank: articles.length + 1,
      title: entry.title,
      url: entry.url,
      category: entry.category,
      image: entry.image,
      bodyText: '',
      paragraphs: [],
      lead: '',
      fetched: false,
    })
  }
  return articles.slice(0, 36)
}

function mergeArticlePages(pages, sourceKey) {
  const byUrl = new Map()
  const order = []

  pages.forEach((html) => {
    parseArticles(html, sourceKey).forEach((article) => {
      const existing = byUrl.get(article.url)
      if (!existing) {
        byUrl.set(article.url, article)
        order.push(article.url)
        return
      }

      // Ranking pages are authoritative for order but often contain only
      // headlines. Category/home pages later in the batch carry the same URL
      // with a thumbnail, so merge that richer duplicate instead of dropping
      // it. This makes cards render images immediately rather than waiting for
      // the slower article-detail enrichment pass.
      byUrl.set(article.url, {
        ...existing,
        title: existing.title || article.title,
        image: existing.image || article.image,
        category: existing.category || article.category,
      })
    })
  })

  return order.map((url) => byUrl.get(url))
}

async function fetchHtml(url, token) {
  const res = await fetch(`/api/proxy?url=${encodeURIComponent(url)}`, {
    headers: { Authorization: `Bearer ${token}` },
  })
  if (!res.ok) throw new Error('Nije dostupno')
  return res.text()
}

function imageDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result)
    reader.onerror = () => reject(reader.error || new Error('image conversion failed'))
    reader.readAsDataURL(blob)
  })
}

function getProxiedImage(src, token) {
  let cached = proxiedImageCache.get(src)
  if (!cached) {
    cached = { url: '', promise: null }
    cached.promise = fetch(`/api/proxy?url=${encodeURIComponent(src)}`, {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then(async (res) => {
        if (!res.ok) throw new Error('image proxy failed')
        const blob = await res.blob()
        if (!blob.type.startsWith('image/')) throw new Error('not an image')
        cached.url = await imageDataUrl(blob)
        return cached.url
      })
      .catch((error) => {
        proxiedImageCache.delete(src)
        throw error
      })
    proxiedImageCache.set(src, cached)
  }
  return cached.url ? Promise.resolve(cached.url) : cached.promise
}

function warmImage(src, token) {
  if (!src) return Promise.resolve('')
  if (proxiedImageCache.get(src)?.url) return Promise.resolve(proxiedImageCache.get(src).url)
  const existing = imageWarmCache.get(src)
  if (existing) return existing
  const promise = new Promise((resolve) => {
    const image = new Image()
    let done = false
    const finish = (value) => {
      if (done) return
      done = true
      resolve(value)
    }
    image.onload = () => {
      const decoded = image.decode ? image.decode().catch(() => {}) : Promise.resolve()
      decoded.then(() => finish(src))
    }
    image.onerror = () => {
      getProxiedImage(src, token).then(finish).catch(() => finish(''))
    }
    image.decoding = 'async'
    image.src = src
  })
  imageWarmCache.set(src, promise)
  promise.then((value) => { if (!value) imageWarmCache.delete(src) })
  return promise
}

function preloadWindow(promise, waitMs = 1800) {
  return Promise.race([
    promise,
    new Promise((resolve) => setTimeout(resolve, waitMs)),
  ])
}

function canonicalInstagramUrl(src) {
  const match = String(src || '').match(/instagram\.com\/(p|reel|tv)\/([A-Za-z0-9_-]+)/i)
  return match ? `https://www.instagram.com/${match[1]}/${match[2]}/` : src
}

function getInstagramPost(src, token) {
  const permalink = canonicalInstagramUrl(src)
  let cached = instagramPostCache.get(permalink)
  if (!cached) {
    cached = { data: null, promise: null }
    const oembed = `https://www.instagram.com/api/v1/oembed/?url=${encodeURIComponent(permalink)}`
    cached.promise = fetchHtml(oembed, token)
      .then((raw) => JSON.parse(raw))
      .then(async (data) => {
        const post = {
          author: cleanText(data.author_name || ''),
          title: cleanText(data.title || ''),
          thumbnail: data.thumbnail_url || '',
        }
        if (!post.thumbnail) throw new Error('Instagram returned no preview image')
        await warmImage(post.thumbnail, token)
        cached.data = post
        return post
      })
      .catch((error) => {
        instagramPostCache.delete(permalink)
        throw error
      })
    instagramPostCache.set(permalink, cached)
  }
  return cached.data ? Promise.resolve(cached.data) : cached.promise
}

function articleMedia(article) {
  const sources = [article.heroImage || article.image]
  ;(article.blocks || []).forEach((block) => {
    if (block.type === 'img') sources.push(block.src)
    if (block.type === 'gallery') (block.images || []).forEach((image) => sources.push(image.src))
    if (block.type === 'nativeVideo' && block.poster) sources.push(block.poster)
  })
  return [...new Set(sources.filter(Boolean))]
}

async function warmArticleContent(article, token) {
  const media = articleMedia(article)
  const instagramBlocks = (article.blocks || []).filter((block) => block.type === 'embed' && block.provider === 'instagram')
  const work = [
    ...media.slice(0, 5).map((src) => warmImage(src, token)),
    ...instagramBlocks.slice(0, 2).map((block) => getInstagramPost(block.src, token)),
  ]
  await Promise.all(work.map((task) => preloadWindow(task)))
  media.slice(5, 12).forEach((src) => { void warmImage(src, token) })
}

function ReliableImage({ src, token, alt = '', className = '', loading, fallback = null }) {
  const [displaySrc, setDisplaySrc] = useState(() => proxiedImageCache.get(src)?.url || src)
  const [failed, setFailed] = useState(false)
  const proxyTriedRef = useRef(false)

  useEffect(() => {
    proxyTriedRef.current = false
    setFailed(false)
    setDisplaySrc(proxiedImageCache.get(src)?.url || src)
  }, [src])

  async function retryThroughMobius() {
    if (!src || proxyTriedRef.current) {
      setFailed(true)
      return
    }
    proxyTriedRef.current = true
    try {
      setDisplaySrc(await getProxiedImage(src, token))
    } catch {
      setFailed(true)
    }
  }

  if (!src || failed) return fallback
  return <img className={className} src={displaySrc} alt={alt} loading={loading} onError={retryThroughMobius} />
}

async function enrichArticle(article, token) {
  if (article.fetched && article.paragraphs?.length) return article
  const html = await fetchHtml(article.url, token)
  const detail = parseArticleDetail(html, article)
  const heroImage = detail.image || article.heroImage || article.image
  return {
    ...article,
    ...detail,
    // Keep the feed thumbnail stable. Detail fetches often find a larger
    // hero image with a different crop; swapping it into the list creates
    // the visible zoom-in/zoom-out effect. If the list had no thumbnail at
    // all, use the article image so the card does not stay as a placeholder.
    image: article.image || detail.image || '',
    heroImage,
    // The ranking headline is the text the reader chose. Keep it stable while
    // the detail document arrives instead of letting small SEO-title changes
    // reflow the reader during its opening transition.
    title: article.title || detail.title,
  }
}

function keywordWord(n) {
  const mod10 = n % 10
  const mod100 = n % 100
  if (mod10 === 1 && mod100 !== 11) return 'riječ'
  return 'riječi'
}

export default function KlixFilter({ appId, token }) {
  const [keywords, setKeywords] = useState(DEFAULT_STATE.keywords)
  const [draft, setDraft] = useState('')
  const [activeTab, setActiveTab] = useState(DEFAULT_STATE.activeTab)
  const [articles, setArticles] = useState({ popular: [], latest: [] })
  const [status, setStatus] = useState('Učitavam Klix...')
  const [error, setError] = useState('')
  const [lastUpdated, setLastUpdated] = useState(null)
  const [storageHydrated, setStorageHydrated] = useState(false)
  const [storageLoadError, setStorageLoadError] = useState(false)
  const [saveError, setSaveError] = useState(false)
  const [saving, setSaving] = useState(false)
  const [refreshing, setRefreshing] = useState(false)
  const [selectedArticle, setSelectedArticle] = useState(null)
  const [openingArticle, setOpeningArticle] = useState(null)
  const [detailError, setDetailError] = useState('')
  const [displayLimit, setDisplayLimit] = useState(10)
  const [filtersOpen, setFiltersOpen] = useState(false)
  const loadMoreRef = useRef(null)
  const listScrollRef = useRef(null)
  const enrichingRef = useRef(new Set())
  const articleNavRef = useRef(null)
  const openRequestRef = useRef(0)
  const articlesRef = useRef(articles)
  const lastSavedStateRef = useRef('')
  const allArticles = useMemo(() => Object.values(articles).flat(), [articles])

  async function refreshFeeds({ quiet = false } = {}) {
    const hadArticles = Object.values(articlesRef.current).some((items) => items.length > 0)
    setError('')
    setRefreshing(true)
    if (!quiet || !hadArticles) setStatus('Učitavam Klix...')
    try {
      const results = await Promise.all(SOURCES.map(async (source) => {
        // Start with the ranking page and add category pages only if it is
        // genuinely sparse. The old all-at-once fan-out made 18 proxy calls
        // per refresh, which could trigger a blank response and replace an
        // otherwise healthy feed.
        const pages = []
        let baseArticles = []
        for (const url of source.urls) {
          const page = await fetchHtml(url, token).catch(() => '')
          if (page) pages.push(page)
          baseArticles = mergeArticlePages(pages, source.key)
          if (baseArticles.length >= 24) break
        }
        const ranked = baseArticles.slice(0, 40).map((article, index) => ({
          ...article,
          id: `${source.key}-${index + 1}`,
          rank: index + 1,
        }))
        return [source.key, ranked]
      }))
      if (!results.some(([, next]) => next.length > 0)) {
        throw new Error('Klix returned no readable articles')
      }
      setArticles((previous) => Object.fromEntries(results.map(([key, next]) => [
        key,
        // A transient upstream response must not wipe the cards and their
        // already-warm images while the reader is open or the user goes back.
        next.length ? next : (previous[key] || []),
      ])))
      setLastUpdated(new Date())
      setStatus('')
    } catch (err) {
      setError('Klix trenutno nije moguće učitati. Pokušaj osvježiti za par trenutaka.')
      if (!quiet || !hadArticles) setStatus('')
    } finally {
      setRefreshing(false)
    }
  }

  useEffect(() => {
    articlesRef.current = articles
  }, [articles])

  useEffect(() => {
    let cancelled = false
    loadState()
      .then((state) => {
        if (cancelled) return
        const serialized = JSON.stringify(state)
        lastSavedStateRef.current = serialized
        setKeywords(state.keywords)
        setActiveTab(state.activeTab)
        setStorageHydrated(true)
      })
      .catch(() => { if (!cancelled) setStorageLoadError(true) })
    return () => { cancelled = true }
  }, [appId, token])

  useEffect(() => {
    let cancelled = false
    async function run() {
      if (cancelled) return
      await refreshFeeds({ quiet: false })
    }
    run()
    const id = setInterval(() => refreshFeeds({ quiet: true }), 1000 * 60 * 10)
    return () => { cancelled = true; clearInterval(id) }
  }, [token])

  // Reader should always open scrolled to the top (not wherever the list was);
  // going back restores the list to its previous scroll position. Keyed on the
  // open/closed boolean so re-renders during article enrichment don't re-scroll.
  const isReader = !!selectedArticle || !!openingArticle
  useEffect(() => {
    if (isReader) {
      window.scrollTo(0, 0)
    } else if (listScrollRef.current != null) {
      const y = listScrollRef.current
      requestAnimationFrame(() => window.scrollTo(0, y))
    }
  }, [isReader])

  useEffect(() => {
    setDisplayLimit(10)
  }, [activeTab, keywords.length])


  useEffect(() => {
    if (!storageHydrated) return undefined
    const nextState = { keywords, activeTab }
    const serialized = JSON.stringify(nextState)
    if (serialized === lastSavedStateRef.current) return undefined
    let active = true
    setSaving(true)
    setSaveError(false)
    const id = setTimeout(() => {
      saveState(nextState)
        .then(() => {
          if (!active) return
          lastSavedStateRef.current = serialized
          setSaveError(false)
        })
        .catch(() => { if (active) setSaveError(true) })
        .finally(() => { if (active) setSaving(false) })
    }, 350)
    return () => { active = false; clearTimeout(id) }
  }, [keywords, activeTab, storageHydrated])

  const current = articles[activeTab] || []
  const decorated = useMemo(() => current.map((article) => ({
    ...article,
    blockedBy: findBlockedKeyword(article, keywords),
  })), [current, keywords])
  const visible = decorated.filter((article) => !article.blockedBy)
  const displayedVisible = visible.slice(0, displayLimit)
  const hidden = decorated.filter((article) => article.blockedBy)
  const activeLabel = SOURCES.find((source) => source.key === activeTab)?.label || 'Klix'
  const hasArticles = current.length > 0
  const isInitialLoading = Boolean(status) && !hasArticles
  const allArticlesHidden = hasArticles && visible.length === 0
  const sourceDescription = activeTab === 'popular'
    ? 'Vijesti koje čitatelji danas najviše otvaraju.'
    : 'Najsvježije objave s Klix.ba, redom kako stižu.'

  useEffect(() => {
    if (selectedArticle) return
    const lookahead = current.slice(0, displayLimit + 5)
    const MAX_CONCURRENT = 3
    const slots = MAX_CONCURRENT - enrichingRef.current.size
    if (slots <= 0) return
    const toEnrich = lookahead
      .filter((a) => !a.fetched && !enrichingRef.current.has(a.url))
      .slice(0, slots)
    toEnrich.forEach((article) => {
      enrichingRef.current.add(article.url)
      enrichArticle(article, token)
        .then((detail) => {
          setArticles((prev) => ({
            ...prev,
            [article.source]: (prev[article.source] || []).map((item) =>
              item.url === article.url ? { ...item, ...detail, image: item.image || detail.image || '', heroImage: detail.heroImage || item.heroImage } : item
            ),
          }))
        })
        .catch(() => {})
        .finally(() => { enrichingRef.current.delete(article.url) })
    })
  }, [current, displayLimit, selectedArticle, token])

  useEffect(() => {
    const node = loadMoreRef.current
    if (!node || selectedArticle) return undefined
    const observer = new IntersectionObserver((entries) => {
      if (entries.some((entry) => entry.isIntersecting)) {
        setDisplayLimit((limit) => Math.min(limit + 10, visible.length))
      }
    }, { root: null, rootMargin: '260px 0px', threshold: 0.01 })
    observer.observe(node)
    return () => observer.disconnect()
  }, [visible.length, selectedArticle])

  function addKeyword() {
    const value = draft.trim()
    if (!value) return
    const exists = keywords.some((kw) => normalizeText(kw) === normalizeText(value))
    if (!exists) setKeywords([...keywords, value])
    setDraft('')
  }

  function removeKeyword(keyword) {
    setKeywords(keywords.filter((kw) => kw !== keyword))
  }

  function handleTabKeyDown(event, sourceKey) {
    if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return
    event.preventDefault()
    const currentIndex = SOURCES.findIndex((source) => source.key === sourceKey)
    const nextIndex = event.key === 'Home'
      ? 0
      : event.key === 'End'
        ? SOURCES.length - 1
        : (currentIndex + (event.key === 'ArrowRight' ? 1 : -1) + SOURCES.length) % SOURCES.length
    const nextKey = SOURCES[nextIndex].key
    setActiveTab(nextKey)
    requestAnimationFrame(() => document.getElementById(`tab-${nextKey}`)?.focus())
  }

  async function openArticle(article) {
    if (!article || selectedArticle?.url === article.url || openingArticle?.url === article.url) return
    const enteringDetail = !selectedArticle && !openingArticle
    if (enteringDetail) {
      // Remember where the list was scrolled so we can restore it on back.
      listScrollRef.current = window.scrollY || document.documentElement.scrollTop || 0
      // The runtime owns browser and Android swipe-back state. Its request is
      // deliberately parallel with the preparation pass so taps feel immediate
      // without revealing a half-loaded reader.
      let handle = null
      handle = window.mobius?.nav?.open?.('klix-article', {
        onBack: () => {
          openRequestRef.current += 1
          articleNavRef.current = null
          setOpeningArticle(null)
          setSelectedArticle(null)
          setDetailError('')
        },
        onForward: () => {
          articleNavRef.current = handle
          setOpeningArticle(null)
          setSelectedArticle(article)
        },
      })
      if (handle) {
        articleNavRef.current = handle
        handle.outcome.then(({ status }) => {
          if (articleNavRef.current !== handle) { handle.close(); return }
          if (status === 'rejected' || status === 'error') articleNavRef.current = null
        }).catch(() => { if (articleNavRef.current === handle) articleNavRef.current = null })
      }
    }

    const request = ++openRequestRef.current
    setOpeningArticle(article)
    setDetailError('')
    try {
      const detailed = article.fetched && article.paragraphs?.length
        ? article
        : await enrichArticle(article, token)
      await warmArticleContent(detailed, token)
      if (openRequestRef.current !== request) return

      setArticles((prev) => ({
        ...prev,
        [article.source]: (prev[article.source] || []).map((item) => item.url === article.url ? detailed : item),
      }))
      setSelectedArticle(detailed)
    } catch {
      if (openRequestRef.current !== request) return
      setSelectedArticle(article)
      setDetailError('Tekst članka trenutno nije dostupan u čitaču. Original možeš otvoriti na Klix.ba.')
    } finally {
      if (openRequestRef.current === request) {
        setOpeningArticle(null)
      }
    }
  }

  function closeArticle() {
    if (!selectedArticle && !openingArticle) return
    openRequestRef.current += 1
    articleNavRef.current?.close()
    articleNavRef.current = null
    setOpeningArticle(null)
    setSelectedArticle(null)
    setDetailError('')
  }

  function handleAppClick(event) {
    const target = event.target.closest?.('[data-article-url]')
    if (!target) return
    event.preventDefault()
    const article = allArticles.find((item) => item.url === target.dataset.articleUrl)
    if (article) openArticle(article)
  }

  return (
    <div className="app" onClick={handleAppClick}>
      <style>{css}</style>

      <header className="siteHeader">
        <div className="brandRow">
          <img className="logoImage" src={LOGO_DATA} alt="Klix Filter" />
          <div className="brandRight">
            <span className="updated">{refreshing ? 'Osvježavam…' : lastUpdated ? `Ažurirano ${lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}` : error ? 'Nije povezano' : 'Spremno'}</span>
            <button className="refresh" onClick={() => refreshFeeds({ quiet: true })} disabled={refreshing}>
              <Reload aria-hidden="true" />
              <span>{refreshing ? 'Osvježavam' : 'Osvježi'}</span>
            </button>
          </div>
        </div>
      </header>

      {selectedArticle || openingArticle ? (
        <ArticleView
          article={selectedArticle || openingArticle}
          preparing={!selectedArticle}
          error={detailError}
          onBack={closeArticle}
          token={token}
        />
      ) : (
        <>
          <section className="filterPanel">
            <div className="tabs" role="tablist" aria-label="Izvor članaka">
              {SOURCES.map((source) => (
                <button
                  key={source.key}
                  id={`tab-${source.key}`}
                  className={activeTab === source.key ? 'tab active' : 'tab'}
                  onClick={() => setActiveTab(source.key)}
                  onKeyDown={(event) => handleTabKeyDown(event, source.key)}
                  role="tab"
                  aria-selected={activeTab === source.key}
                  aria-controls="feed-panel"
                  tabIndex={activeTab === source.key ? 0 : -1}
                >
                  {source.label}
                </button>
              ))}
            </div>

            <div className="keywordBox">
              <button className="filterTitle filterToggle" onClick={() => setFiltersOpen((open) => !open)} aria-expanded={filtersOpen}>
                <span className="filterLabel"><Filter aria-hidden="true" /><strong>Filteri sadržaja</strong></span>
                <span className="filterToggleMeta">
                  {keywords.length} {keywordWord(keywords.length)} · {hidden.length} sakriveno
                  <ChevronDown className={filtersOpen ? 'chev open' : 'chev'} aria-hidden="true" />
                </span>
              </button>
              {filtersOpen && (
                <div className="filterBody">
                  <div className="addRow">
                    <input
                      value={draft}
                      onChange={(e) => setDraft(e.target.value)}
                      onKeyDown={(e) => { if (e.key === 'Enter') addKeyword() }}
                      placeholder="npr. politika, rat, reality..."
                      aria-label="Nova riječ za skrivanje"
                    />
                    <button onClick={addKeyword} aria-label="Dodaj filter"><Plus aria-hidden="true" /><span>Dodaj</span></button>
                  </div>
                  <div className="chips">
                    {keywords.length === 0 ? <span className="emptyChip">Nema skrivenih riječi</span> : keywords.map((kw) => (
                      <button className="chip" key={kw} onClick={() => removeKeyword(kw)} aria-label={`Ukloni filter ${kw}`}>
                        <span>{kw}</span><X aria-hidden="true" />
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </section>

          <div id="feed-panel" className="feedPanel" role="tabpanel" aria-labelledby={`tab-${activeTab}`}>
            <section className="sectionHeader" aria-live="polite">
              <div>
                <h1>{activeLabel}</h1>
                <p>{sourceDescription}</p>
              </div>
              {hasArticles ? (
                <div className="countBadge" aria-label={`${visible.length} vidljivih, ${hidden.length} skrivenih članaka`}>
                  <strong>{visible.length}</strong>
                  <span>{hidden.length ? `${hidden.length} skriveno` : 'članaka'}</span>
                </div>
              ) : null}
            </section>

            {isInitialLoading ? (
              <div className="skeletonGrid" aria-label="Učitavam članke" aria-busy="true">
                <div className="skeletonCard leadSkeleton" aria-hidden="true"><span></span><i></i><i></i></div>
                <div className="skeletonCard" aria-hidden="true"><span></span><i></i><i></i></div>
                <div className="skeletonCard" aria-hidden="true"><span></span><i></i><i></i></div>
              </div>
            ) : null}

            {error && hasArticles ? (
              <div className="notice error inlineError" role="status">
                <span>{error} Prikazujem posljednje učitane vijesti.</span>
                <button onClick={() => refreshFeeds({ quiet: true })} disabled={refreshing}><Reload aria-hidden="true" /> Pokušaj ponovo</button>
              </div>
            ) : null}

            {error && !hasArticles ? (
              <section className="emptyState errorState" role="alert">
                <div>
                  <strong>Klix trenutno nije dostupan</strong>
                  <p>Veza prema izvoru nije uspjela. Sačekaj trenutak pa pokušaj ponovo.</p>
                </div>
                <button onClick={() => refreshFeeds({ quiet: true })} disabled={refreshing}><Reload aria-hidden="true" /> Pokušaj ponovo</button>
              </section>
            ) : null}

            {hasArticles ? (
              <main className={refreshing ? 'feed isRefreshing' : 'feed'}>
                {displayedVisible.map((article, index) => <ArticleCard key={article.url} article={article} lead={index === 0} onOpen={openArticle} token={token} />)}
                {allArticlesHidden ? (
                  <div className="emptyState filteredEmpty">
                    <div><strong>Sve vijesti su skrivene</strong><p>Prilagodi filtere da ponovo vidiš članke.</p></div>
                    <button onClick={() => setFiltersOpen(true)}><Filter aria-hidden="true" /> Otvori filtere</button>
                  </div>
                ) : null}
                {visible.length > displayedVisible.length && (
                  <button className="loadMore" onClick={() => setDisplayLimit((limit) => Math.min(limit + 10, visible.length))}>
                    Učitaj još ({visible.length - displayedVisible.length})
                  </button>
                )}
                <div ref={loadMoreRef} className="scrollSentinel" aria-hidden="true"></div>
              </main>
            ) : null}
          </div>

          {hidden.length > 0 && (
            <details className="hiddenList">
              <summary>Sakriveni članci ({hidden.length})</summary>
              {hidden.map((article) => (
                <a key={article.url} href={`#article=${encodeURIComponent(article.url)}`} data-article-url={article.url}>
                  <span>{article.title}</span>
                  <em>zbog: {article.blockedBy}</em>
                </a>
              ))}
            </details>
          )}
        </>
      )}

      <footer role="status">
        {storageLoadError
          ? 'Spremljeni filteri nisu učitani; promjene se neće spremiti.'
          : saveError
            ? 'Filteri nisu spremljeni. Sljedeća promjena će pokušati ponovo.'
            : saving
              ? 'Čuvam filtere…'
              : 'Filteri se čuvaju automatski.'}
      </footer>
    </div>
  )
}

function ArticleCard({ article, lead, onOpen, token }) {
  return (
    <article
      className={lead ? 'card leadCard' : 'card'}
      data-article-url={article.url}
      role="button"
      tabIndex={0}
      onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onOpen(article) } }}
    >
      <div className="cardLink">
        {article.image ? (
          <ReliableImage
            className="thumb"
            src={article.image}
            token={token}
            alt=""
            loading="lazy"
            fallback={<div className="thumb fallback" aria-hidden="true"></div>}
          />
        ) : <div className="thumb fallback" aria-hidden="true"></div>}
        <div className="body">
          <div className="meta"><span className="category">{article.category}</span><span>#{article.rank}</span><span>{article.source === 'popular' ? 'Najčitanije' : 'Najnovije'}</span></div>
          <h2>{article.title}</h2>
          {lead && article.lead ? <p className="leadPreview">{article.lead}</p> : null}
        </div>
      </div>
    </article>
  )
}

function ArticleGallery({ images, token }) {
  const [activeIndex, setActiveIndex] = useState(null)
  const closeButtonRef = useRef(null)
  const active = activeIndex == null ? null : images[activeIndex]
  function move(direction) {
    setActiveIndex((index) => (index == null ? null : (index + direction + images.length) % images.length))
  }
  useEffect(() => {
    if (activeIndex == null) return undefined
    const previousOverflow = document.documentElement.style.overflow
    document.documentElement.style.overflow = 'hidden'
    requestAnimationFrame(() => closeButtonRef.current?.focus())
    function onKeyDown(event) {
      if (event.key === 'Escape') setActiveIndex(null)
      if (event.key === 'ArrowLeft') move(-1)
      if (event.key === 'ArrowRight') move(1)
    }
    window.addEventListener('keydown', onKeyDown)
    return () => {
      window.removeEventListener('keydown', onKeyDown)
      document.documentElement.style.overflow = previousOverflow
    }
  }, [activeIndex, images.length])
  return (
    <>
      <section className="inlineGallery" aria-label="Galerija fotografija">
        <div className="galleryHeader"><strong>Galerija fotografija</strong><span>{images.length} fotografija</span></div>
        <div className="galleryStrip">
          {images.map((image, imageIndex) => (
            <button key={`${image.src}-${imageIndex}`} className="galleryItem" onClick={() => setActiveIndex(imageIndex)} aria-label={`Otvori fotografiju ${imageIndex + 1} od ${images.length}`}>
              <ReliableImage src={image.src} token={token} alt={image.caption || `Fotografija ${imageIndex + 1}`} loading="lazy" />
              <span className="galleryCount">{imageIndex + 1} / {images.length}</span>
              {image.caption ? <span className="galleryCaption">{image.caption}</span> : null}
            </button>
          ))}
        </div>
      </section>
      {active ? (
        <div className="galleryViewer" role="dialog" aria-modal="true" aria-label={`Fotografija ${activeIndex + 1} od ${images.length}`}>
          <button ref={closeButtonRef} className="galleryClose" onClick={() => setActiveIndex(null)} aria-label="Zatvori galeriju"><X aria-hidden="true" /></button>
          <button className="galleryNav previous" onClick={() => move(-1)} aria-label="Prethodna fotografija"><ChevronLeft aria-hidden="true" /></button>
          <figure className="galleryStage">
            <ReliableImage src={active.src} token={token} alt={active.caption || `Fotografija ${activeIndex + 1}`} />
            <figcaption>{active.caption || `Fotografija ${activeIndex + 1} od ${images.length}`}</figcaption>
          </figure>
          <button className="galleryNav next" onClick={() => move(1)} aria-label="Sljedeća fotografija"><ChevronRight aria-hidden="true" /></button>
        </div>
      ) : null}
    </>
  )
}

function ExternalMediaLink({ provider = '', src, kind = 'embed' }) {
  const isInstagram = provider === 'instagram'
  const label = isInstagram
    ? 'Pogledaj objavu na Instagramu'
    : kind === 'video'
      ? 'Pogledaj video na Klix.ba'
      : 'Pogledaj originalnu objavu'
  return (
    <aside className="externalMedia" aria-label={label}>
      <strong>{isInstagram ? 'Instagram objava' : 'Video'}</strong>
      <span>{isInstagram ? 'Ova objava trenutno nije dostupna za prikaz.' : 'Video se otvara na originalnoj stranici.'}</span>
      <a href={src} target="_blank" rel="noreferrer">{label} <ArrowUpRight aria-hidden="true" /></a>
    </aside>
  )
}

function InstagramPost({ src, token }) {
  const permalink = canonicalInstagramUrl(src)
  const [post, setPost] = useState(() => instagramPostCache.get(permalink)?.data || null)
  const [unavailable, setUnavailable] = useState(false)

  useEffect(() => {
    let cancelled = false
    setUnavailable(false)
    setPost(instagramPostCache.get(permalink)?.data || null)
    getInstagramPost(permalink, token)
      .then((next) => { if (!cancelled) setPost(next) })
      .catch(() => { if (!cancelled) setUnavailable(true) })
    return () => { cancelled = true }
  }, [permalink, token])

  if (unavailable) return <ExternalMediaLink provider="instagram" src={permalink} />
  if (!post) {
    return (
      <section className="instagramPost instagramLoading" aria-label="Učitavam Instagram objavu" aria-busy="true">
        <div className="instagramHeader"><span className="instagramAvatar" aria-hidden="true"></span><span>Instagram</span></div>
        <div className="instagramShimmer" aria-hidden="true"></div>
      </section>
    )
  }
  return (
    <article className="instagramPost">
      <a href={permalink} target="_blank" rel="noreferrer" className="instagramLink" aria-label="Otvori objavu na Instagramu">
        <div className="instagramHeader">
          <span className="instagramAvatar" aria-hidden="true"></span>
          <span>Instagram</span>
          {post.author ? <strong>@{post.author}</strong> : null}
        </div>
        <ReliableImage className="instagramImage" src={post.thumbnail} token={token} alt={post.title || 'Instagram objava'} />
        <div className="instagramBody">
          {post.title ? <p>{post.title}</p> : null}
          <span>Pogledaj objavu na Instagramu <ArrowUpRight aria-hidden="true" /></span>
        </div>
      </a>
    </article>
  )
}

function videoPreview(src) {
  const id = youtubeIdFromUrl(src)
  if (!id) return null
  return {
    href: `https://www.youtube.com/watch?v=${encodeURIComponent(id)}`,
    thumbnail: `https://i.ytimg.com/vi/${encodeURIComponent(id)}/hqdefault.jpg`,
  }
}

function VideoPreview({ src, token }) {
  const preview = videoPreview(src)
  if (!preview) return <ExternalMediaLink src={src} kind="video" />
  return (
    <a className="videoPreview" href={preview.href} target="_blank" rel="noreferrer">
      <ReliableImage className="videoPreviewImage" src={preview.thumbnail} token={token} alt="Pregled videa" />
      <span className="videoPlay" aria-hidden="true"><Play /></span>
      <span className="videoPreviewLabel">Pogledaj video</span>
    </a>
  )
}

function ArticleView({ article, preparing, error, onBack, token }) {
  const initialHeroRef = useRef({ articleUrl: article.url, src: article.heroImage || article.image || '' })
  if (initialHeroRef.current.articleUrl !== article.url) {
    initialHeroRef.current = { articleUrl: article.url, src: article.heroImage || article.image || '' }
  } else if (!initialHeroRef.current.src && (article.heroImage || article.image)) {
    initialHeroRef.current.src = article.heroImage || article.image
  }
  const readerImage = initialHeroRef.current.src
  const blocks = (article.blocks && article.blocks.length)
    ? article.blocks
    : (article.paragraphs || []).map((text) => ({ type: 'p', text }))
  return (
    <main className="reader" aria-busy={preparing || undefined}>
      <button className="backButton" onClick={onBack}><ArrowLeft aria-hidden="true" /> Nazad na listu</button>
      <div className="readerMeta"><span>{article.category}</span><span>{article.source === 'popular' ? 'Najčitanije' : 'Najnovije'}</span></div>
      <h1>{article.title}</h1>
      {readerImage
        ? <ReliableImage className="readerImage" src={readerImage} token={token} alt={article.caption || ''} />
        : preparing
          ? <div className="readerImagePlaceholder" aria-hidden="true"><span></span></div>
          : null}
      {preparing ? <p className="readerPreparing">Pripremam članak…</p> : null}
      {!preparing && article.caption ? <p className="caption">{article.caption}</p> : null}
      {!preparing && article.author ? <p className="readerByline">Piše {article.author}</p> : null}
      {!preparing && article.lead ? <p className="readerLead">{article.lead}</p> : null}
      {error ? <div className="notice error readerError" role="status">{error}</div> : null}
      <section className="articleText">
        {!preparing && blocks.map((block, index) => {
          if (block.type === 'p') return <p key={index}>{block.text}</p>
          if (block.type === 'h') return <h3 key={index} className="articleHeading">{block.text}</h3>
          if (block.type === 'img') return (
            <figure key={index} className="inlineFigure">
              <ReliableImage src={block.src} token={token} alt={block.caption || ''} loading="lazy" />
              {block.caption ? <figcaption>{block.caption}</figcaption> : null}
            </figure>
          )
          if (block.type === 'gallery') return (
            <ArticleGallery key={index} images={block.images} token={token} />
          )
          if (block.type === 'video') return <VideoPreview key={index} src={block.src} token={token} />
          if (block.type === 'embed' && block.provider === 'instagram') return <InstagramPost key={index} src={block.src} token={token} />
          if (block.type === 'embed') return <ExternalMediaLink key={index} src={block.src} provider={block.provider} />
          if (block.type === 'nativeVideo') return <ExternalMediaLink key={index} src={block.src} kind="video" />
          return null
        })}
      </section>
      <a className="sourceLink" href={article.url} target="_blank" rel="noreferrer">Otvori original na Klix.ba <ArrowUpRight aria-hidden="true" /></a>
    </main>
  )
}

